const QUIZ = TILE_CONFIG;

// -- SCORING -- IRB LOCKED ------------------------------------------------------
const RAW = [0,33,67,100];
function scoreAnswer(qi,ai){ return QUIZ[qi].reverse ? RAW[3-ai] : RAW[ai]; }
function computeScores(answers){
const tiles=QUIZ.map((q,i)=>({
id:q.id,tile:q.tile,domain:q.domain,imgSrc:q.imgSrc,question:q.question,
score:answers[i]!=null?scoreAnswer(i,answers[i]):null,
answerIndex:answers[i],
answerText:answers[i]!=null?q.options[answers[i]]:null}));
const avg=dom=>{const ds=tiles.filter(t=>t.domain===dom&&t.score!=null);return ds.length?Math.round(ds.reduce((s,t)=>s+t.score,0)/ds.length):0;};
const home=avg("HOME"),work=avg("WORK"),social=avg("SOCIAL");
return{home,work,social,overall:Math.round((home+work+social)/3),tiles};
}
function zone(s){return s<=33?"red":s<=67?"yellow":"green";}
function zc(s){if(s==null)return"#9ca3af";const z=zone(s);return z==="red"?"#d32f2f":z==="yellow"?"#f5c518":"#2e7d32";}
function zbg(s){const z=zone(s);return z==="red"?"#ffebee":z==="yellow"?"#fffde7":"#e8f5e9";}
// function zl(z){return z==="red"?"Elevated":z==="yellow"?"Moderate":"Healthy";}
function useW(){
const[w,setW]=useState(typeof window!=="undefined"?window.innerWidth:400);
useEffect(()=>{let t;const h=()=>{clearTimeout(t);t=setTimeout(()=>setW(window.innerWidth),200);};window.addEventListener("resize",h);return()=>{window.removeEventListener("resize",h);clearTimeout(t);};},[]);
return{isD:w>=900};
}
function loadH(){
try{
  const raw=JSON.parse(localStorage.getItem("o2os_h")||"[]");
  // Filter out corrupt sessions where tiles have no scores (pre-fix data)
  return raw.filter(s=>s.scores&&s.scores.tiles&&s.scores.tiles.some(t=>t.score!=null));
}catch{return[];}
}
function saveS(scores){
const h=loadH();
// Strip imgSrc before saving — images are ~300KB each, localStorage limit is 5MB
const leanTiles=scores.tiles?scores.tiles.map(({imgSrc,...t})=>t):[];
const leanScores={...scores,tiles:leanTiles};
const s={id:Date.now(),date:new Date().toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}),scores:leanScores};
h.unshift(s);localStorage.setItem("o2os_h",JSON.stringify(h.slice(0,20)));return s;
}

