// -- GAUGE -- pure CSS, zero JS state, zero re-renders -----------------------
function Gauge({label,score,animDelay=0}){
const pct=score||0;
return(
<div style={{marginBottom:28}}>
<span style={{fontFamily:"system-ui,sans-serif",fontWeight:700,fontSize:17,color:"#111"}}>{label}</span>
<div style={{position:"relative",height:44,overflow:"visible",marginTop:10}}>
<div style={{display:"flex",height:"100%",borderRadius:8,overflow:"hidden",boxShadow:"inset 0 1px 3px rgba(0,0,0,0.15)"}}>
<div style={{flex:"33 0 0",background:"#d32f2f"}}/>
<div style={{flex:"34 0 0",background:"#f5c518"}}/>
<div style={{flex:"33 0 0",background:"#2e7d32"}}/>
</div>
<style>{`
@keyframes gaugeSlide_${label}{from{left:0%}to{left:${pct}%}}
@keyframes gaugeFade_${label}{from{opacity:0}to{opacity:1}}
`}</style>
<div style={{
position:"absolute",top:"50%",
left:pct+"%",
transform:"translate(-50%,-50%)",
animation:`gaugeSlide_${label} 1.1s cubic-bezier(0.25,0.46,0.45,0.94) ${animDelay}s both, gaugeFade_${label} 0.3s ease ${animDelay}s both`,
fontFamily:"'Courier New',monospace",fontWeight:900,fontSize:24,color:"#fff",
textShadow:"0 0 6px rgba(0,0,0,0.9),0 0 12px rgba(0,0,0,0.6)",
lineHeight:1,pointerEvents:"none",whiteSpace:"nowrap"}}>{score}</div>
<div style={{
position:"absolute",top:"100%",marginTop:3,
left:pct+"%",
transform:"translateX(-50%)",
animation:`gaugeSlide_${label} 1.1s cubic-bezier(0.25,0.46,0.45,0.94) ${animDelay}s both, gaugeFade_${label} 0.3s ease ${animDelay}s both`,
width:0,height:0,
borderLeft:"9px solid transparent",borderRight:"9px solid transparent",
borderBottom:"11px solid rgba(0,0,0,0.35)"}}/>
</div>
</div>
);
}

