// -- HISTORY -------------------------------------------------------------------
function History({history,onBack,onView}){
if(!history.length)return(
<div style={{minHeight:"100vh",background:"#f5f6f8",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:32}}>
<div style={{fontFamily:"Georgia,serif",fontSize:24,color:"#1a2744",marginBottom:14}}>No history yet</div>
<button onClick={onBack} style={{background:"#1a2744",border:"none",borderRadius:12,padding:"14px 36px",color:"#fff",fontFamily:"system-ui,sans-serif",fontWeight:700,fontSize:16,cursor:"pointer"}}> Back</button>
</div>
);
return(
<div style={{minHeight:"100vh",background:"#f5f6f8"}}>
<div style={{background:"#1a2744",padding:"10px 16px 12px"}}>
<div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
<div onClick={onBack} style={{cursor:"pointer",WebkitTapHighlightColor:"transparent"}}><CACLogo size={32}/></div>
<div style={{textAlign:"center",flex:1}}>
<div style={{fontSize:9,color:"rgba(255,255,255,0.4)",letterSpacing:"0.1em",marginBottom:1}}>O2OS™ · STRESS NUMBER™</div>
<div style={{fontWeight:700,fontSize:15,color:"#fff"}}>My History</div>
<div style={{fontSize:10,color:"rgba(255,255,255,0.3)",marginTop:1}}>{history.length} assessment{history.length!==1?"s":""}</div>
</div>
<button onClick={onBack} style={{background:"rgba(255,255,255,0.1)",border:"none",borderRadius:7,padding:"6px 10px",color:"rgba(255,255,255,0.7)",fontFamily:"system-ui,sans-serif",fontSize:12,fontWeight:600,cursor:"pointer"}}>Back</button>
</div>
</div>
{history.length>=2&&(()=>{
const pts=[...history].reverse().slice(-6);
const W=340,H=110,PL=28,PR=12,PT=10,PB=22,cW=W-PL-PR,cH=H-PT-PB;
const xp=i=>pts.length===1?PL+cW/2:PL+(i/(pts.length-1))*cW;
const yp=v=>PT+cH-(v/100)*cH;
const LINE={home:"#2563eb",work:"#ea580c",social:"#a855f7"};
return(
<div style={{background:"#fff",margin:"12px 12px 0",borderRadius:12,padding:"16px"}}>
<div style={{fontFamily:"system-ui,sans-serif",fontWeight:700,fontSize:12,color:"#888",letterSpacing:"0.08em",marginBottom:10}}>TREND</div>
<svg viewBox={`0 0 ${W} ${H}`} style={{width:"100%",overflow:"visible"}}>
{/* Clean background */}
<rect x={PL} y={PT} width={cW} height={cH} fill="#f9fafb"/>
{/* Y-axis zone strips -- left rail */}
<rect x={PL-8} y={yp(100)} width={5} height={yp(68)-yp(100)} fill="#2e7d32" rx="2"/>
<rect x={PL-8} y={yp(67)} width={5} height={yp(34)-yp(67)} fill="#f5c518" rx="2"/>
<rect x={PL-8} y={yp(33)} width={5} height={yp(0)-yp(33)} fill="#d32f2f" rx="2"/>
{/* Threshold dashes */}
<line x1={PL} y1={yp(67)} x2={PL+cW} y2={yp(67)} stroke="#2e7d32" strokeWidth="0.5" strokeDasharray="3,4" opacity="0.35"/>
<line x1={PL} y1={yp(33)} x2={PL+cW} y2={yp(33)} stroke="#d32f2f" strokeWidth="0.5" strokeDasharray="3,4" opacity="0.35"/>
{/* Grid lines */}
{[100,67,33,0].map(v=>(
<g key={v}>
<line x1={PL} y1={yp(v)} x2={PL+cW} y2={yp(v)} stroke="#e5e7eb" strokeWidth={v===67||v===33?"0":"0.5"}/>
<text x={PL-12} y={yp(v)+3} textAnchor="end" fontSize="8" fill="#bbb" fontFamily="monospace">{v}</text>
</g>
))}
{/* 3 lines: home, work, social */}
{[["home",LINE.home],["work",LINE.work],["social",LINE.social]].map(([k,col])=>(
<g key={k}>
{pts.length>1&&<polyline fill="none" stroke={col} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round"
points={pts.map((s,i)=>`${xp(i)},${yp(s.scores[k])}`).join(" ")}/>}
{pts.map((s,i)=><circle key={i} cx={xp(i)} cy={yp(s.scores[k])} r={3} fill="#fff" stroke={col} strokeWidth="2"/>)}
</g>
))}
{/* X-axis date labels */}
{pts.map((s,i)=>(
<text key={i} x={xp(i)} y={H-5} textAnchor="middle" fontSize="8" fill="#aaa" fontFamily="system-ui,sans-serif">
{s.date.split(" ")[0]}
</text>
))}
</svg>
{/* Legend */}
<div style={{display:"flex",gap:16,justifyContent:"center",marginTop:8}}>
{[["home","Home",LINE.home],["work","Work",LINE.work],["social","Social",LINE.social]].map(([k,l,col])=>(
<div key={k} style={{display:"flex",alignItems:"center",gap:4}}>
<div style={{width:18,height:3,background:col,borderRadius:2}}/>
<span style={{fontFamily:"system-ui,sans-serif",fontSize:11,color:"#666"}}>{l}</span>
</div>
))}
</div>
</div>
);
})()}
<div style={{padding:12}}>
{history.map(s=>{
// const sc=zc(s.scores.overall);
return(
<div key={s.id} onClick={()=>onView(s)} style={{background:"#fff",borderRadius:12,padding:"16px 18px",marginBottom:10,cursor:"pointer",display:"flex",justifyContent:"space-between",alignItems:"center",border:"1px solid #f0f0f0",boxShadow:"0 1px 4px rgba(0,0,0,0.05)"}}>
<div>
<div style={{fontFamily:"system-ui,sans-serif",fontSize:14,color:"#555",marginBottom:6}}>{s.date}</div>
<div style={{display:"flex",gap:16}}>
{[["H",s.scores.home],["W",s.scores.work],["S",s.scores.social]].map(([l,v])=>(
<span key={l} style={{fontFamily:"'Courier New',monospace",fontSize:14,fontWeight:700,color:zc(v)}}>{l}:{v}</span>
))}
</div>
</div>
<div style={{textAlign:"right"}}>
<div style={{fontFamily:"Georgia,serif",fontWeight:700,fontSize:16,color:"#1a2744",lineHeight:1.2}}>Stress Number™</div>

          </div>
        </div>
      );
    })}
  </div>
</div>

);
}

