// -- APP -----------------------------------------------------------------------
export default function App(){
const{isD}=useW();
// Single session state object -- atomic update, no split-state race conditions
const[history,setHistory]=useState(loadH);
const _initHistory=loadH();
const _lastSess=_initHistory[0]||null;
const[session,setSession]=useState({
  screen:"welcome",
  qi:0,
  answers:Array(30).fill(null),
  scores:_lastSess?_lastSess.scores:null,
  date:_lastSess?_lastSess.date:"",
  viewSess:null
});
const S=session;

function go(patch){setSession(prev=>({...prev,...patch}));}

function start(){go({screen:"quiz",qi:0,answers:Array(30).fill(null),scores:null,date:"",viewSess:null});}

function handleAnswer(idx,ai,advance=false){
if(advance){
if(idx===29){
// Set answer first so navy shows, then transition to results
setSession(prev=>{
const next=[...prev.answers];next[idx]=ai;
return{...prev,answers:next};
});
setTimeout(()=>{
setSession(prev=>{
const scores=computeScores(prev.answers);
const sess=saveS(scores);
setTimeout(()=>setHistory(loadH()),500);
return{...prev,scores,date:sess.date,screen:"results",viewSess:null};
});
},180);
}else{
// Set answer first — shows navy selection flash
setSession(prev=>{const next=[...prev.answers];next[idx]=ai;return{...prev,answers:next};});
// Then advance after 180ms so user sees the navy
setTimeout(()=>setSession(prev=>({...prev,qi:idx+1})),180);
}
}else{
setSession(prev=>{const next=[...prev.answers];next[idx]=ai;return{...prev,answers:next};});
}
}

const activeScores=S.viewSess?S.viewSess.scores:S.scores;
const activeDate=S.viewSess?S.viewSess.date:S.date;

return(
<div style={{maxWidth:isD?520:"100%",margin:"0 auto",minHeight:"100vh",boxShadow:isD?"0 0 60px rgba(0,0,0,0.15)":"none"}}>
{S.screen==="welcome"&&<Welcome onStart={start} history={history} onHistory={()=>go({screen:"history"})} onSettings={()=>go({screen:"settings"})}/>}
{S.screen==="quiz"&&<Quiz qi={S.qi} currentAnswer={S.answers[S.qi]} answeredCount={S.answers.filter(a=>a!=null).length} onAnswer={handleAnswer} onHome={()=>go({screen:"welcome"})} isD={isD}/>}
{S.screen==="results"&&S.scores&&<Results scores={activeScores} date={activeDate} onRetake={start} onHistory={()=>go({screen:"history",viewSess:null})} onSettings={()=>go({screen:"settings"})} isD={isD}/>}
{S.screen==="history"&&<History history={S.viewSess?[S.viewSess]:history} onBack={()=>go({screen:S.scores?"results":"welcome",viewSess:null})} onView={s=>go({viewSess:s,scores:s.scores,date:s.date,screen:"results"})} isD={isD}/>}
{S.screen==="settings"&&<SettingsScreen onBack={()=>go({screen:S.scores?"results":"welcome"})}/>}
</div>
);
}